/* READ ONLY Teradata SQL Assistant. Run each numbered SELECT separately.
Full populations, no account sample; no permanent tables/config/run changes.
Uses the analyst-confirmed numeric special list. Counts are account-month events.
Keep the source fixed and reconcile baseline counts to saved results first.
FLOAT casts precede arithmetic. NULL numeric outputs indicate invalid source grain;
absence of rows is not a pass. No individual account results should be uploaded.
*/
/* Input states are mutually exclusive diagnostic labels, NOT a full replication of CASE precedence. Inspect code + state together; numeric input validity still requires confirmation. */
WITH src AS (SELECT AGMT_ID,CAST(FACT_DT AS DATE) AS POU_DT,EXTRACT(YEAR FROM FACT_DT)*12+EXTRACT(MONTH FROM FACT_DT) AS MK,COUNT(*) OVER (PARTITION BY AGMT_ID,EXTRACT(YEAR FROM FACT_DT),EXTRACT(MONTH FROM FACT_DT)) AS KC,CAST(TOTAL_DEPOSIT_SAVINGS_BALANCE AS FLOAT) AS TOTAL_DEPOSIT_SAVINGS_BALANCE,CAST(PCKG_BALANCE_AMT AS FLOAT) AS PCKG_BALANCE_AMT,CAST(PCKG_REPAY_AMT AS FLOAT) AS PCKG_REPAY_AMT,CAST(PCKG_ORIG_LOAN_EXCL_WHSE_AMT AS FLOAT) AS PCKG_ORIG_LOAN_EXCL_WHSE_AMT,CAST(PCKG_BORR_TOP2_TOTAL_INC_AMT AS FLOAT) AS PCKG_BORR_TOP2_TOTAL_INC_AMT,CAST(MV_PCKG_SAV_DEP_TO_BALANCE_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_BALANCE_RT,CAST(MV_PCKG_SAV_DEP_TO_REPAY_RT AS FLOAT) AS MV_PCKG_SAV_DEP_TO_REPAY_RT,CAST(MV_PCKG_LOAN_TO_INC_RT AS FLOAT) AS MV_PCKG_LOAN_TO_INC_RT,CAST(MV_PCKG_REPAY_TO_INC_RT AS FLOAT) AS MV_PCKG_REPAY_TO_INC_RT FROM LAB_T_ORION_MVT.VW_RDS_PHASE2_FACT WHERE CAST(FACT_DT AS DATE) IN (DATE '2013-11-30',DATE '2013-12-31',DATE '2014-01-31',DATE '2016-10-31',DATE '2016-11-30',DATE '2016-12-31',DATE '2018-10-31',DATE '2018-11-30',DATE '2018-12-31')), vals AS (SELECT CAST('MV_PCKG_SAV_DEP_TO_BALANCE_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_SAV_DEP_TO_BALANCE_RT AS V,TOTAL_DEPOSIT_SAVINGS_BALANCE AS NUM,PCKG_BALANCE_AMT AS DEN FROM src UNION ALL SELECT CAST('MV_PCKG_SAV_DEP_TO_REPAY_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_SAV_DEP_TO_REPAY_RT AS V,TOTAL_DEPOSIT_SAVINGS_BALANCE AS NUM,PCKG_REPAY_AMT AS DEN FROM src UNION ALL SELECT CAST('MV_PCKG_LOAN_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_LOAN_TO_INC_RT AS V,PCKG_ORIG_LOAN_EXCL_WHSE_AMT AS NUM,PCKG_BORR_TOP2_TOTAL_INC_AMT AS DEN FROM src UNION ALL SELECT CAST('MV_PCKG_REPAY_TO_INC_RT' AS VARCHAR(64)) AS FIELD_NAME,AGMT_ID,POU_DT,MK,KC,MV_PCKG_REPAY_TO_INC_RT AS V,PCKG_REPAY_AMT AS NUM,PCKG_BORR_TOP2_TOTAL_INC_AMT/CAST(12 AS FLOAT) AS DEN FROM src), st AS (SELECT F.*,CASE WHEN V IS NULL THEN 'MISSING' WHEN V IN (-99999,-999999,-999998,-99998,-99997,-9999,-9998,-999997,-999993,-999,-999995,999999,999998,999990,99999,99998,999.99,999.88,999,9999,9998) THEN 'SPECIAL' ELSE 'VALID' END AS VS FROM vals F),
h AS (SELECT S.*,LAG(VS) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PS,LEAD(VS) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS NS,LAG(MK) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS PM,LEAD(MK) OVER (PARTITION BY FIELD_NAME,AGMT_ID ORDER BY MK) AS NM FROM st S),
ctl AS (SELECT SUM(CASE WHEN AGMT_ID IS NULL OR KC<>1 THEN 1 ELSE 0 END) AS BAD FROM src),
f AS (SELECT H.*,CASE WHEN NUM IS NULL THEN 'NUM_NULL' WHEN NUM=0 THEN 'NUM_ZERO' WHEN DEN IS NULL THEN 'DEN_NULL' WHEN DEN=0 THEN 'DEN_ZERO' WHEN DEN<0 THEN 'DEN_NEGATIVE' ELSE 'OTHER_INPUT_STATE' END AS INPUT_STATE FROM h H
 WHERE POU_DT IN (DATE '2013-12-31',DATE '2016-11-30',DATE '2018-11-30') AND VS='SPECIAL' AND PS='VALID' AND MK-PM=1)
SELECT FIELD_NAME,POU_DT,V AS SPECIAL_CODE,INPUT_STATE,
 CASE WHEN MAX(BAD)=0 THEN COUNT(*) END AS VALID_TO_SPECIAL_COUNT,
 CASE WHEN MAX(BAD)=0 THEN SUM(CASE WHEN NM-MK=1 AND NS='VALID' THEN 1 ELSE 0 END) END AS TEMP_SPECIAL_COUNT
FROM f CROSS JOIN ctl GROUP BY FIELD_NAME,POU_DT,V,INPUT_STATE ORDER BY FIELD_NAME,POU_DT,SPECIAL_CODE,INPUT_STATE;
